        evt.StatusText("The well is dry today.")
        return
    end
    Xeen.markToday("d6_warding_well")
    evt.ForPlayer(Players.All)
    AddValue(FireResistanceBonus, 20)
    AddValue(AirResistanceBonus, 20)
    AddValue(WaterResistanceBonus, 20)
    AddValue(EarthResistanceBonus, 20)
    evt.StatusText("+20 Fire, Air, Water and Earth resistance until you rest.", 5)
end, "The Well of Warding")

